function fnResponse(module, fn, input) {
  const score = Math.round((0.3 + Math.random() * 0.7) * 100) / 100;
  return {
    version: '3.316.0',
    module,
    function: fn,
    input,
    score,
    ts: new Date().toISOString()
  };
}

http.createServer((req, res) => {
  const parsed = url.parse(req.url, true);
  const path = parsed.pathname;
  res.setHeader('Content-Type', 'application/json');

  if (path === '/health') {
    res.end(JSON.stringify({ status: 'ok', version: '3.316.0' }));
    return;
  }

  if (path === '/api/v1/pcc-catalog/modules') {
    res.end(JSON.stringify(CATALOG));
    return;
  }

  if (path === '/api/v1/pcc-catalog/categories') {
    res.end(JSON.stringify({ version: CATALOG.version, count: CATALOG.categories.length, categories: {} }));
    return;
  }

  // /api/v1/<slug>/list
  const listMatch = path.match(/^\/api\/v1\/(pcc-[a-z0-9-]+)\/list$/);
  if (listMatch) {
    res.end(JSON.stringify({ version: '3.316.0', module: listMatch[1].replace(/-/g, '_'), functions: ['MockFn1', 'MockFn2', 'MockFn3'] }));
    return;
  }

  // /api/v1/<slug>/call/<fn>
  const callMatch = path.match(/^\/api\/v1\/(pcc-[a-z0-9-]+)\/call\/([^\/]+)$/);
  if (callMatch && req.method === 'POST') {
    let body = '';
    req.on('data', (c) => body += c);
    req.on('end', () => {
      const input = body ? JSON.parse(body) : {};
      res.end(JSON.stringify(fnResponse(callMatch[1].replace(/-/g, '_'), callMatch[2], input)));
    });
    return;
  }

  // /api/v1/<slug>/record
  const recMatch = path.match(/^\/api\/v1\/(pcc-[a-z0-9-]+)\/record$/);
  if (recMatch && req.method === 'POST') {
    let body = '';
    req.on('data', (c) => body += c);
    req.on('end', () => {
      const req_body = body ? JSON.parse(body) : {};
      res.end(JSON.stringify({
        version: '3.316.0',
        module: recMatch[1].replace(/-/g, '_'),
        function: req_body.fn || 'Unknown',
        tenant_id: req_body.tenant_id,
        decisionId: req_body.decisionId,
        result: fnResponse(recMatch[1].replace(/-/g, '_'), req_body.fn || 'Unknown', req_body.input),
        recorded: true,
        created_by: req_body.created_by,
        ts: new Date().toISOString()
      }));
    });
    return;
  }

  res.statusCode = 404;
  res.end(JSON.stringify({ error: 'not found', path }));
}).listen(PORT, () => {
  console.log('PCC Mock Server listening on http://localhost:' + PORT);
  console.log('Use this URL in SDK tests:');
  console.log('  PCC_BASE=http://localhost:' + PORT);
});
